examples.question_text:
Sketch the inverse of $f(x)=(x-2)^2$, $x\ge2$, on the same axes. Label its endpoint.
[tikz]
\begin{tikzpicture}[x=8mm,y=8mm,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\definecolor{curveBlue}{HTML}{268CFF}
\draw[->,black] (-1,0)--(6.3,0) node[right] {$x$};
\draw[->,black] (0,-1)--(0,6.3) node[above] {$y$};
\foreach \t in {2,4,6} {\draw[black] (\t,-0.08)--(\t,0.08);\path (\t,0) node[below,font=\fontsize{8.5}{10}\selectfont] {$\t$};\draw[black] (-0.08,\t)--(0.08,\t);\path (0,\t) node[left,font=\fontsize{8.5}{10}\selectfont] {$\t$};}
\draw[dashed,black] (-1,-1)--(6,6);
\draw[thick,curveBlue,->,domain=2:4.45,samples=80] plot (\x,{(\x-2)*(\x-2)});
\fill[black] (2,0) circle (1.4pt);
\path (2,0) node[below right,yshift=-7pt] {$(2,0)$};
\path (3.8,5.7) node[left,text=curveBlue] {$f$};
\end{tikzpicture}
[/tikz]

examples.solution_text:
Reflect the selected branch in $y=x$. Interchanging the endpoint coordinates gives the closed endpoint $(0,2)$.
[tikz]
\begin{tikzpicture}[x=8mm,y=8mm,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\definecolor{curveBlue}{HTML}{268CFF}
\definecolor{curveRed}{HTML}{EF6068}
\draw[->,black] (-1,0)--(6.3,0) node[right] {$x$};
\draw[->,black] (0,-1)--(0,6.3) node[above] {$y$};
\foreach \t in {2,4,6} {\draw[black] (\t,-0.08)--(\t,0.08);\path (\t,0) node[below,font=\fontsize{8.5}{10}\selectfont] {$\t$};\draw[black] (-0.08,\t)--(0.08,\t);\path (0,\t) node[left,font=\fontsize{8.5}{10}\selectfont] {$\t$};}
\draw[dashed,black] (-1,-1)--(6,6);
\draw[thick,curveBlue,->,domain=2:4.45,samples=80] plot (\x,{(\x-2)*(\x-2)});
\draw[thick,curveRed,->,domain=2:4.45,samples=80] plot ({(\x-2)*(\x-2)},\x);
\fill[black] (2,0) circle (1.4pt);
\fill[black] (0,2) circle (1.4pt);
\path (0,2) node[above left] {$(0,2)$};
\path (3.8,5.7) node[left,text=curveBlue] {$f$};
\path (5.7,4.4) node[above,text=curveRed] {$f^{-1}$};
\end{tikzpicture}
[/tikz]

examples.question_text:
Sketch the inverse of the line shown on the same axes. Label its intercepts.
[tikz]
\begin{tikzpicture}[x=7mm,y=7mm,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\draw[->,black] (-4.5,0)--(4.5,0) node[right] {$x$};
\draw[->,black] (0,-4.5)--(0,4.5) node[above] {$y$};
\draw[dashed,black] (-4,-4)--(4,4);
\draw[thick,black,<->] (-0.5,-4)--(3.5,4);
\fill[black] (0,-3) circle (1.2pt);
\fill[black] (1.5,0) circle (1.2pt);
\path (0,-3) node[left] {$(0,-3)$};
\path (1.5,0) node[below right] {$(\frac32,0)$};
\end{tikzpicture}
[/tikz]

examples.solution_text:
Reflect the line in $y=x$. The intercepts $(0,-3)$ and $(\frac32,0)$ become $(-3,0)$ and $(0,\frac32)$. Draw the straight line through these reflected points.
[tikz]
\begin{tikzpicture}[x=7mm,y=7mm,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\definecolor{curveBlue}{HTML}{268CFF}
\definecolor{curveRed}{HTML}{EF6068}
\draw[->,black] (-4.5,0)--(4.5,0) node[right] {$x$};
\draw[->,black] (0,-4.5)--(0,4.5) node[above] {$y$};
\draw[dashed,black] (-4,-4)--(4,4);
\draw[thick,curveBlue,<->] (-0.5,-4)--(3.5,4);
\draw[thick,curveRed,<->] (-4,-0.5)--(4,3.5);
\fill[black] (-3,0) circle (1.2pt);
\fill[black] (0,1.5) circle (1.2pt);
\path (-3,0) node[below] {$(-3,0)$};
\path (0,1.5) node[above left] {$(0,\frac32)$};
\path (3.5,4) node[left,text=curveBlue] {$f$};
\path (4,3.5) node[right,text=curveRed] {$f^{-1}$};
\end{tikzpicture}
[/tikz]

